const patterns=[
 [/^正在加载全身模型 (\d+)%$/,m=>`Loading the full-body model: ${m[1]}%`],
 [/^数字人画面生成中 ([\d.]+)%$/,m=>`Rendering the digital presenter: ${m[1]}%`],
 [/^(\d+) \/ (\d+)\s+(.+)$/,m=>`${m[1]} / ${m[2]} — ${dictionary[m[3]]||m[3]}`],
 [/^单独试听 (.+)$/,m=>`Solo: ${dictionary[m[1]]||m[1]}`],
 [/^第 (\d+) 页$/,m=>`Page ${m[1]}`],
 [/^上传 (\d+) \/ (\d+)$/,m=>`Uploading ${m[1]} / ${m[2]}`],
 [/^待校对曲谱 (.+)$/,m=>`Score awaiting review ${m[1]}`],
 [/^目标 (\d+) BPM$/,m=>`Target: ${m[1]} BPM`],
 [/^原谱标记速度\s+(\d+) BPM$/,m=>`Score tempo: ${m[1]} BPM`],
 [/^第 (\d+) 小节\s+(\d+) \/ (\d+) 组$/,m=>`Measure ${m[1]} · ${m[2]} / ${m[3]} onsets`],
 [/^(\d+) 组起音\s+(\d+) 小节(.*)$/,m=>`${m[1]} onsets · ${m[2]} measures${m[3].replace('原谱','Score tempo').replace('示例谱','Sample score')}`],
 [/^正在准备：(.+) · (.+)$/,m=>`Preparing: ${dictionary[m[1]]||m[1]} — ${dictionary[m[2]]||m[2]}`],
 [/^正在播放：(.+) · (.+)$/,m=>`Playing: ${dictionary[m[1]]||m[1]} — ${dictionary[m[2]]||m[2]}`],
 [/^导师讲解已准备 (\d+)\/(\d+) 段；另有唐秋鸣介绍 1 段(?:；其余 (\d+) 段待生成)?$/,m=>`${m[1]} of ${m[2]} supervisor chapters ready, plus Qiuming’s introduction${m[3]?`. ${m[3]} chapters are not yet available.`:''}`],
 [/^当前步骤：(.+)。后台正在处理，页面操作不会中断此任务。$/,m=>`Current step: ${dictionary[m[1]]||m[1]}. Processing continues in the background.`],
 [/^处理失败：(.+)。任务已停止，其他后台任务不会受影响；可以点击“重试”重新处理。$/,m=>`Task failed: ${dictionary[m[1]]||m[1]}. Other tasks will continue. Select Retry to try again.`],
 [/^(.+)老师，您好。$/,m=>`Welcome, Professor ${m[1]}.`]
];
export function translateDynamic(text){for(const [pattern,render] of patterns){const match=text.match(pattern);if(match)return render(match);}return null;}
